def solve():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        N = int(line)
    except ValueError:
        return

    # Iterate through candidate numbers starting from N
    # Since N is between 100 and 999, the answer will be at most 999 (e.g., 999)
    # or possibly 111, 222, ... 999. If N is 100, next same-digit number is 111.
    # The maximum possible answer in range is 999.

    candidate = N
    while True:
        s = str(candidate)
        if len(set(s)) == 1:
            print(candidate)
            return
        candidate += 1

if __name__ == "__main__":
    solve()

